conversationSummary += `Escalation Reason: Customer asked for fibre availability / human assistance\n\n`;
conversationSummary += `--- Recent Conversation ---\n`;
recentMessages.forEach(h => {
  if (h.incoming_message) conversationSummary += `Customer: ${h.incoming_message}\n`;
  if (h.ai_response) conversationSummary += `Layla: ${h.ai_response}\n`;
});
conversationSummary += `\nCustomer's latest message: ${p.incomingMessage}\n`;
conversationSummary += `Layla's response: ${p.aiResponse}\n`;

// Format phone number for Chatwoot (ensure + prefix)
let chatwootPhone = p.phoneNumber;
if (!chatwootPhone.startsWith('+')) {
  chatwootPhone = '+' + chatwootPhone;
}

return {
  json: {
    phoneNumber: chatwootPhone,
    contactName: contactName || 'Unknown',
    email: email,
    address: address,
    recommendedPackage: recommendedPackage,
    leadScore: p.leadScore,
