try { products = $('Fetch Products').all().map(i => i.json).filter(p => p && p.name); } catch (e) {}
const validPrices = new Set();
const validSpeeds = new Set();
for (const p of products) {
  if (p.price_cents != null && p.price_cents > 0) validPrices.add(p.price_cents / 100);
  if (p.speed_down) validSpeeds.add(Number(p.speed_down));
  if (p.speed_up) validSpeeds.add(Number(p.speed_up));
}

const issues = [];
let m;

// 1) Prices — every "R<amount>"/"ZAR <amount>" quoted must be a real catalog
// price. \b before the currency marker avoids matching letters inside words
// (e.g. the "r" in "our 40").
const priceRe = /\b(?:ZAR|R)\s*(\d[\d\s]*(?:\.\d{1,2})?)/gi;
const quotedPrices = [];
while ((m = priceRe.exec(replyText)) !== null) {
