while ((m = pairRe.exec(replyText)) !== null) { quotedSpeeds.push(Number(m[1]), Number(m[2])); }
const gbpsRe = /(\d+(?:\.\d+)?)\s*Gbps/gi;
while ((m = gbpsRe.exec(replyText)) !== null) quotedSpeeds.push(Math.round(parseFloat(m[1]) * 1000));
const mbpsRe = /(\d{1,4})\s*Mbps/gi;
while ((m = mbpsRe.exec(replyText)) !== null) quotedSpeeds.push(Number(m[1]));
const badSpeeds = [...new Set(quotedSpeeds.filter(v => !validSpeeds.has(v)))];
if (badSpeeds.length) issues.push('quoted speeds not in catalog: ' + badSpeeds.join(', ') + ' Mbps');

