return { json: Object.assign({}, upstream, { _verify: Object.assign({}, verify, {
  safeToSend: issues.length === 0 ? 'yes' : 'no',
  issues: issues,
  retryAllowed: retriesUsed < 2 ? 'yes' : 'no',
  jev: { answers: answers, cost: (jevResult.usage && jevResult.usage.cost) || null }
}) }) };

// Extract message data from Meta WhatsApp webhook payload
const webhookData = $input.first().json;
const body = webhookData.body || webhookData;

let phoneNumber = '';
let messageText = '';
let messageId = '';
let contactName = '';
let metaTimestamp = '';

if (body.entry && body.entry[0] && body.entry[0].changes && body.entry[0].changes[0]) {
  const change = body.entry[0].changes[0];
  if (change.value && change.value.messages && change.value.messages[0]) {
    const msg = change.value.messages[0];
    phoneNumber = msg.from || '';
    messageId = msg.id || '';
    metaTimestamp = msg.timestamp || '';
    const type = msg.type || 'text';

    switch (type) {
      case 'text':
        messageText = msg.text?.body || '';
        break;
      case 'button':
        messageText = msg.button?.text || '';
        break;
      case 'interactive':
        messageText = msg.interactive?.button_reply?.title || msg.interactive?.list_reply?.title || '';
        break;
      case 'location': {
        // Customers often send their address as a location pin — surface it
        // to the AI as readable text so Layla can capture it.
        const loc = msg.location || {};
        const parts = [];
        if (loc.name) parts.push(loc.name);
        if (loc.address) parts.push(loc.address);
        if (loc.latitude != null && loc.longitude != null) {
          parts.push('(coordinates: ' + loc.latitude + ', ' + loc.longitude + ')');
        }
        messageText = 'Customer sent their location' + (parts.length ? ': ' + parts.join(' ') : '');
        break;
      }
      case 'image':
        messageText = 'Customer sent an image' + (msg.image?.caption ? ' with caption: ' + msg.image.caption : '');
        break;
      case 'video':
        messageText = 'Customer sent a video' + (msg.video?.caption ? ' with caption: ' + msg.video.caption : '');
        break;
      case 'document':
        messageText = 'Customer sent a document' + (msg.document?.caption ? ' with caption: ' + msg.document.caption : (msg.document?.filename ? ' (' + msg.document.filename + ')' : ''));
        break;
      case 'audio':
      case 'voice':
        messageText = 'Customer sent a voice note. Audio cannot be transcribed — politely ask them to type their reply or repeat it in a text message.';
        break;
      case 'sticker':
        messageText = 'Customer sent a sticker.';
        break;
      case 'contacts': {
        const c = (msg.contacts || [])[0] || {};
        const n = c.name?.formatted_name || '';
        const p = (c.phones || [])[0]?.phone || '';
        messageText = 'Customer shared a contact' + (n ? ': ' + n : '') + (p ? ' ' + p : '');
        break;
      }
      case 'reaction':
        // Emoji reactions are not messages — skip AI processing entirely.
        return [];
      default:
        messageText = 'Customer sent a ' + type + ' message.';
    }

    if (change.value.contacts && change.value.contacts[0]) {
      contactName = change.value.contacts[0].profile?.name || '';
    }
  }
}

// Skip status update webhooks (delivered, read) that have no message content
if (!phoneNumber || !messageText) {
  return [];
}

// Normalize to canonical international digits: strip non-digits, SA local 0-prefix -> 27
phoneNumber = phoneNumber.replace(/[^0-9]/g, '');
if (/^0\d{9}$/.test(phoneNumber)) phoneNumber = '27' + phoneNumber.slice(1);

const sessionId = phoneNumber;

return {
  json: {
    phoneNumber,
    sessionId,
    messageText,
    messageId,
    contactName,
    metaTimestamp,
    timestamp: new Date().toISOString()
  }
};

