// Extract email, address, name from conversation history
let email = null;
let address = null;
let contactName = p.contactName || null;
let recommendedPackage = null;

// Search through conversation history for contact details
history.forEach(h => {
  const text = (h.incoming_message || '') + ' ' + (h.ai_response || '');

  // Extract email
  if (!email) {
    const emailMatch = text.match(/[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/i);
    if (emailMatch) email = emailMatch[0];
  }

  // Extract address (look for road/street/avenue patterns in user messages)
  if (!address && h.incoming_message) {
    const addrMatch = h.incoming_message.match(/\d+\s+\w+\s+(?:road|street|avenue|drive|place|close|blvd)\s*,?\s*\w+/i);
    if (addrMatch) address = addrMatch[0];
  }

  // Extract package recommendation from AI responses
  if (!recommendedPackage && h.ai_response) {
    const pkgMatch = h.ai_response.match(/(\d+\/?\d*\s*Mbps[^]*?R\d+\/month)/i);
    if (pkgMatch) recommendedPackage = pkgMatch[0];
  }
});

// Build conversation summary for Chatwoot
